import { useState } from "react"
import { motion } from "motion/react"

import { cn } from "@/lib/utils"

import type { WobbleCardProps } from "@/components/ui/wobble-card-types"

/**
 * Wobble Card (Aceternity UI) — reimplementação padronizada shadcn.
 *
 * O card "balança" seguindo o cursor: o wrapper externo translada
 * proporcionalmente à posição do mouse, e o conteúdo interno faz o
 * movimento inverso + leve scale (1.03), criando a sensação de
 * profundidade/parallax. Inclui um noise overlay translúcido (SVG
 * fractalNoise inline, sem dependência externa) para textura sutil.
 *
 * - data-slot="wobble-card"          → wrapper externo (recebe o tilt)
 * - data-slot="wobble-card-content"  → conteúdo interno (inverse-tilt + scale)
 *
 * Ajustes em relação ao JSON original da Aceternity:
 *  - removido "use client" (Vite/React puro);
 *  - bg-indigo-800 → bg-card (token semântico shadcn, reage ao tema);
 *  - noise.webp → SVG fractalNoise inline (zero dependência).
 */
function WobbleCard({
  children,
  containerClassName,
  className,
}: WobbleCardProps) {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 })
  const [isHovering, setIsHovering] = useState(false)

  const handleMouseMove = (event: React.MouseEvent<HTMLElement>) => {
    const { clientX, clientY } = event
    const rect = event.currentTarget.getBoundingClientRect()
    const x = (clientX - (rect.left + rect.width / 2)) / 20
    const y = (clientY - (rect.top + rect.height / 2)) / 20
    setMousePosition({ x, y })
  }

  return (
    <motion.section
      data-slot="wobble-card"
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => {
        setIsHovering(false)
        setMousePosition({ x: 0, y: 0 })
      }}
      style={{
        transform: isHovering
          ? `translate3d(${mousePosition.x}px, ${mousePosition.y}px, 0) scale3d(1, 1, 1)`
          : "translate3d(0px, 0px, 0) scale3d(1, 1, 1)",
        transition: "transform 0.1s ease-out",
      }}
      className={cn(
        "mx-auto w-full min-h-[500px] bg-card relative rounded-2xl overflow-hidden",
        containerClassName,
      )}
    >
      <div
        className="relative h-full [background-image:radial-gradient(88%_100%_at_top,rgba(255,255,255,0.5),rgba(255,255,255,0))] sm:mx-0 sm:rounded-2xl overflow-hidden"
        style={{
          boxShadow:
            "0 10px 32px rgba(34, 42, 53, 0.12), 0 1px 1px rgba(0, 0, 0, 0.05), 0 0 0 1px rgba(34, 42, 53, 0.05), 0 4px 6px rgba(34, 42, 53, 0.08), 0 24px 108px rgba(47, 48, 55, 0.10)",
        }}
      >
        <motion.div
          data-slot="wobble-card-content"
          style={{
            transform: isHovering
              ? `translate3d(${-mousePosition.x}px, ${-mousePosition.y}px, 0) scale3d(1.03, 1.03, 1)`
              : "translate3d(0px, 0px, 0) scale3d(1, 1, 1)",
            transition: "transform 0.1s ease-out",
          }}
          className={cn("h-full px-4 py-20 sm:px-10", className)}
        >
          <Noise />
          {children}
        </motion.div>
      </div>
    </motion.section>
  )
}

/**
 * Camada de ruído sutil (SVG fractalNoise inline). Não-exportada para
 * satisfazer o react-refresh/only-export-components.
 */
function Noise() {
  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 w-full h-full scale-[1.2] transform opacity-10 [mask-image:radial-gradient(#fff,transparent,75%)]"
      style={{
        backgroundImage:
          "url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.85'/></svg>\")",
        backgroundSize: "30%",
      }}
    />
  )
}

export { WobbleCard }

import * as React from "react"

/**
 * Tipos do Wobble Card (Aceternity UI), reimplementado padronizado shadcn.
 *
 * Mantido em arquivo separado (.ts puro, sem JSX) para satisfazer o
 * react-refresh/only-export-components (o .tsx só exporta o componente).
 */

/**
 * Card Aceternity que "balança" seguindo o cursor: o wrapper translada
 * proporcionalmente à posição do mouse, e o conteúdo interno faz o
 * movimento inverso + leve scale (≈ 1.03), criando a sensação de
 * profundidade. Inclui um noise overlay (SVG fractalNoise) para textura.
 */
export type WobbleCardProps = {
  /** Conteúdo renderizado sobre o noise overlay. */
  children?: React.ReactNode
  /** Classes extras aplicadas no container externo (mexem no tilt). */
  containerClassName?: string
  /** Classes extras aplicadas no conteúdo interno (mexem no inverse-tilt). */
  className?: string
}
